"use client";

/**
 * QR-and-poll payment: issue an invoice, show a code the user scans in
 * their banking app, wait for the provider to confirm.
 *
 * Four states, and all four are reachable: preparing the invoice,
 * waiting for payment, paid, and failed. The waiting state is the one
 * that matters — it has to stay honest for as long as a person takes
 * to open another app, find the right account, and confirm, without
 * either spinning forever or giving up while they are mid-payment.
 * So polling stops at `timeoutMs` with a "still waiting?" message and
 * a retry, rather than silently going quiet.
 *
 * Provider work happens server-side through `@/actions/payment` (see
 * `@/lib/local-payment`): the browser never sees provider credentials,
 * and never says who is paying — that comes from the session.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { CheckCircle2, XCircle } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";
import { CURRENCY } from "@/lib/billing-config";
import { paymentPollConfig } from "@/lib/payment-poll-config";
import { pollLocalPayment, startLocalPayment } from "@/actions/payment";
import type { LocalPaymentInvoice } from "@/lib/local-payment";

type Step = "creating" | "waiting" | "timedOut" | "paid" | "failed";

interface LocalPaymentModalProps {
  open: boolean;
  onClose: () => void;
  /** What is being bought — a plan slug, a bundle id, an order id. */
  reference: string;
  /** Amount to display. The server prices the invoice itself. */
  amount: number;
  /** Localized name of what is being bought. */
  label: string;
  /** Called once the provider confirms payment. */
  onPaid: () => void;
}

export function LocalPaymentModal({
  open,
  onClose,
  reference,
  amount,
  label,
  onPaid,
}: LocalPaymentModalProps) {
  const t = useTranslations("payment-poll");
  const format = useFormatter();

  const [step, setStep] = useState<Step>("creating");
  const [invoice, setInvoice] = useState<LocalPaymentInvoice | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);

  // `onPaid` is usually an inline arrow; holding it in a ref keeps the
  // polling effect from restarting on every parent render.
  const onPaidRef = useRef(onPaid);
  onPaidRef.current = onPaid;

  const createInvoice = useCallback(async () => {
    setStep("creating");
    setError(null);
    const result = await startLocalPayment(reference, amount);
    if (!result.success) {
      setError(result.error);
      setStep("failed");
      return;
    }
    setInvoice(result.data);
    setStep("waiting");
  }, [reference, amount]);

  useEffect(() => {
    if (!open) return;
    void createInvoice();
  }, [open, attempt, createInvoice]);

  useEffect(() => {
    if (step !== "waiting" || !invoice) return;

    const { pollIntervalMs, timeoutMs } = paymentPollConfig;
    const startedAt = Date.now();

    const timer = setInterval(async () => {
      if (Date.now() - startedAt > timeoutMs) {
        clearInterval(timer);
        setStep("timedOut");
        return;
      }

      const result = await pollLocalPayment(invoice.invoiceId);
      // A failed poll is not a failed payment — the provider may just
      // be slow. Keep waiting; the timeout is the only give-up.
      if (!result.success) return;

      if (result.data === "paid") {
        clearInterval(timer);
        setStep("paid");
        setTimeout(() => onPaidRef.current(), 1200);
      } else if (result.data === "failed") {
        clearInterval(timer);
        setError(t("errors.declined"));
        setStep("failed");
      }
    }, pollIntervalMs);

    return () => clearInterval(timer);
  }, [step, invoice, t]);

  const description =
    step === "creating"
      ? t("state.creating")
      : step === "waiting"
        ? t("state.waiting")
        : step === "timedOut"
          ? t("state.timedOut")
          : step === "paid"
            ? t("state.paid")
            : t("state.failed");

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-center">
            {t("title", {
              label,
              amount: format.number(amount, {
                style: "currency",
                currency: CURRENCY,
                maximumFractionDigits: 0,
              }),
            })}
          </DialogTitle>
          <DialogDescription className="text-center">
            {description}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col items-center py-4">
          {step === "creating" ? (
            <Spinner className="size-8 text-primary" aria-hidden />
          ) : null}

          {step === "waiting" && invoice ? (
            <>
              {invoice.qrCode ? (
                // A plain <img>: the QR is usually a data: URI minted
                // per invoice, so there is nothing for next/image to
                // optimize, and a remote QR host would need adding to
                // next.config's remotePatterns in every consumer.
                <img
                  src={invoice.qrCode}
                  alt={t("qrAlt")}
                  width={200}
                  height={200}
                  className="mb-4 rounded-xl bg-white p-4"
                />
              ) : null}

              {invoice.deeplinks?.length ? (
                <div className="mt-2 w-full space-y-2">
                  <p className="mb-2 text-center text-xs text-muted-foreground">
                    {t("orChooseApp")}
                  </p>
                  {invoice.deeplinks.map((link) => (
                    <Button
                      key={link.url}
                      variant="outline"
                      className="w-full"
                      render={<a href={link.url} />}
                      nativeButton={false}
                    >
                      {link.app}
                    </Button>
                  ))}
                </div>
              ) : null}

              <div className="mt-4 flex items-center gap-2 text-sm text-muted-foreground">
                <Spinner className="size-3.5" aria-hidden />
                <span>{t("state.polling")}</span>
              </div>
            </>
          ) : null}

          {step === "timedOut" ? (
            <div className="space-y-3 text-center">
              <p className="text-sm text-muted-foreground">
                {t("timedOutHelp")}
              </p>
              <Button onClick={() => setAttempt((n) => n + 1)}>
                {t("retry")}
              </Button>
            </div>
          ) : null}

          {step === "paid" ? (
            <div className="text-center">
              <CheckCircle2
                className="mx-auto size-16 text-primary"
                aria-hidden
              />
              <p className="mt-4 text-lg font-semibold">{t("paidTitle")}</p>
              <p className="mt-1 text-sm text-muted-foreground">
                {t("paidBody", { label })}
              </p>
            </div>
          ) : null}

          {step === "failed" ? (
            <div className="text-center">
              <XCircle
                className="mx-auto size-16 text-destructive"
                aria-hidden
              />
              <p className="mt-4 text-lg font-semibold">{t("failedTitle")}</p>
              <p className="mt-1 text-sm text-muted-foreground">{error}</p>
              <div className="mt-4 flex justify-center gap-2">
                <Button onClick={() => setAttempt((n) => n + 1)}>
                  {t("retry")}
                </Button>
                <Button variant="outline" onClick={onClose}>
                  {t("close")}
                </Button>
              </div>
            </div>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use server";

/**
 * Transport for the QR-and-poll payment flow — thin over the provider
 * binding in `@/lib/local-payment`.
 *
 * Both actions require a signed-in caller and never accept a user id
 * from the browser: who is paying is a session fact, not a parameter.
 * The provider binding decides what an invoice costs; `reference` only
 * names what is being bought, and your implementation is responsible
 * for pricing it server-side rather than trusting `amount` — which is
 * why `amount` is not in this signature at all.
 */

import { getTranslations } from "next-intl/server";

import { requireAuth } from "@intelligo-dev/auth";

import {
  checkLocalPaymentStatus,
  createLocalPayment,
  type LocalPaymentInvoice,
  type LocalPaymentStatus,
} from "@/lib/local-payment";

export type PaymentActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

export async function startLocalPayment(
  reference: string,
  amount: number
): Promise<PaymentActionResult<LocalPaymentInvoice>> {
  const t = await getTranslations("payment-poll");

  try {
    await requireAuth();
  } catch {
    return { success: false, error: t("errors.unauthorized") };
  }

  try {
    const invoice = await createLocalPayment({ reference, amount });
    return { success: true, data: invoice };
  } catch {
    // Provider errors can carry account identifiers and endpoint
    // details; the caller gets the generic message.
    return { success: false, error: t("errors.createFailed") };
  }
}

export async function pollLocalPayment(
  invoiceId: string
): Promise<PaymentActionResult<LocalPaymentStatus>> {
  const t = await getTranslations("payment-poll");

  try {
    await requireAuth();
  } catch {
    return { success: false, error: t("errors.unauthorized") };
  }

  try {
    return { success: true, data: await checkLocalPaymentStatus(invoiceId) };
  } catch {
    return { success: false, error: t("errors.statusFailed") };
  }
}

import "server-only";

/**
 * Local payment provider binding — consumer-owned.
 *
 * Card checkout is a redirect: you send the user to the processor and
 * they come back. Most of the world's payment methods are not that.
 * QR-and-poll — QPay and SocialPay in Mongolia, PIX in Brazil, UPI in
 * India, PromptPay in Thailand — issues an invoice, shows a code the
 * user scans in their own banking app, and waits for the provider to
 * say it was paid. `LocalPaymentModal` renders that flow; this file is
 * where you bind it to an actual provider.
 *
 * Both functions run on the server, and neither takes a user id: the
 * caller is resolved from the session inside your implementation. A
 * client-supplied user id on a payment call is an invitation to
 * charge someone else's plan to a stranger's account.
 *
 * The default throws rather than returning a fake invoice — a payment
 * flow that silently no-ops is worse than one that is obviously
 * unbound.
 */

export interface LocalPaymentInvoice {
  /** Provider's invoice id; passed back to `checkLocalPaymentStatus`. */
  invoiceId: string;
  /** QR image as a data: URI or an absolute URL. */
  qrCode?: string;
  /** Banking apps that can settle this invoice directly. */
  deeplinks?: { app: string; url: string }[];
}

export type LocalPaymentStatus = "pending" | "paid" | "failed";

export interface LocalPaymentRequest {
  /** Amount in the currency `lib/billing-config.ts` declares. */
  amount: number;
  /** What is being bought — a plan slug, a credit bundle id, an order. */
  reference: string;
}

export async function createLocalPayment(
  _request: LocalPaymentRequest
): Promise<LocalPaymentInvoice> {
  throw new Error(
    "createLocalPayment is not bound. Implement it in lib/local-payment.ts " +
      "against your payment provider, or remove the payment-poll item."
  );
}

export async function checkLocalPaymentStatus(
  _invoiceId: string
): Promise<LocalPaymentStatus> {
  throw new Error(
    "checkLocalPaymentStatus is not bound. Implement it in lib/local-payment.ts " +
      "against your payment provider, or remove the payment-poll item."
  );
}

/**
 * Polling behaviour for the QR payment modal — consumer-owned.
 *
 * `pollIntervalMs`: how often to ask the provider whether the invoice
 * settled. Three seconds is a compromise: fast enough that the success
 * screen feels immediate, slow enough not to hammer a provider that
 * rate-limits status reads.
 *
 * `timeoutMs`: when to stop asking and offer a retry instead. Five
 * minutes is long enough for someone to switch apps, log into their
 * bank, and confirm — the common case that a shorter timeout would
 * cut off mid-payment.
 */

export interface PaymentPollConfig {
  pollIntervalMs: number;
  timeoutMs: number;
}

export const paymentPollConfig: PaymentPollConfig = {
  pollIntervalMs: 3_000,
  timeoutMs: 5 * 60_000,
};
